/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `Pages` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL,
  `menu_label` varchar(100) DEFAULT NULL,
  `menu_group` varchar(100) DEFAULT NULL,
  `menu_order` int(11) DEFAULT 0,
  `code` mediumtext DEFAULT NULL,
  `tables_used` varchar(500) DEFAULT NULL COMMENT 'Comma-separated list of transaction tables this page interacts with',
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=40 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;
INSERT INTO `Pages` VALUES
(1,'tools/gst-rules-audit','GST Rules Audit','Tools',1,'<?php\n$pdo = DB::conn();\nif (isset($_GET[\"run\"])) {\n    header(\"Content-Type: text/plain\");\n    $sql = \"SELECT a.id AS rule_a, b.id AS rule_b,\n                   a.hsn_chapter, a.gst_rate, b.gst_rate\n            FROM gst_rate_rules a\n            JOIN gst_rate_rules b\n              ON a.hsn_chapter = b.hsn_chapter\n             AND a.id < b.id\n            WHERE a.gst_rate <> b.gst_rate\";\n    foreach ($pdo->query($sql) as $row) {\n        echo \"Conflict: Rule {$row[\"rule_a\"]} vs {$row[\"rule_b\"]}\n\";\n    }\n};?>','gst_rate_rules'),
(2,'invoices/post','Post Invoice','Invoices',1,'<?php\n$pdo = DB::conn();\n\n// Handle form submission\nif ($_SERVER[\"REQUEST_METHOD\"] === \"POST\") {\n    try {\n        $pdo->beginTransaction();\n\n        // Fetch party details\n        $partyStmt = $pdo->prepare(\"SELECT id, gstin, name, party_type, address, city, state FROM parties WHERE id = ?\");\n        $partyStmt->execute([$_POST[\"party_id\"]]);\n        $party = $partyStmt->fetch();\n\n        if (!$party) {\n            throw new Exception(\"Party not found\");\n        }\n\n        // Insert invoice\n        $invoiceStmt = $pdo->prepare(\"\n            INSERT INTO invoices (\n                invoice_no, invoice_date, party_id, party_name, party_gstin, \n                party_address, party_state, inv_type, place_of_supply, \n                taxable_amount, cgst_amount, sgst_amount, igst_amount, \n                total_amount, status\n            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)\n        \");\n        \n        $invoiceStmt->execute([\n            $_POST[\"invoice_no\"],\n            $_POST[\"invoice_date\"], \n            $party[\"id\"],\n            $party[\"name\"],\n            $party[\"gstin\"],\n            $party[\"address\"] . \", \" . $party[\"city\"],\n            $party[\"state\"],\n            $_POST[\"inv_type\"] ?? \"B2B\",\n            $_POST[\"place_of_supply\"] ?? $party[\"state\"],\n            $_POST[\"taxable_amount\"] ?? 0,\n            $_POST[\"cgst_amount\"] ?? 0,\n            $_POST[\"sgst_amount\"] ?? 0, \n            $_POST[\"igst_amount\"] ?? 0,\n            $_POST[\"total_amount\"] ?? 0,\n            \"DRAFT\"\n        ]);\n\n        $invoiceId = $pdo->lastInsertId();\n\n        // Insert invoice items\n        if (isset($_POST[\"items\"]) && is_array($_POST[\"items\"])) {\n            $itemStmt = $pdo->prepare(\"\n                INSERT INTO invoice_items (\n                    invoice_id, item_id, description, hsn, quantity, rate, \n                    discount_percent, cgst_rate, sgst_rate, igst_rate\n                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)\n            \");\n\n            foreach ($_POST[\"items\"] as $item) {\n                $itemStmt->execute([\n                    $invoiceId,\n                    $item[\"item_id\"] ?? null,\n                    $item[\"description\"] ?? \"\",\n                    $item[\"hsn\"] ?? \"\",\n                    $item[\"quantity\"] ?? 1,\n                    $item[\"rate\"] ?? 0,\n                    $item[\"discount_percent\"] ?? 0,\n                    $item[\"cgst_rate\"] ?? 0,\n                    $item[\"sgst_rate\"] ?? 0,\n                    $item[\"igst_rate\"] ?? 0\n                ]);\n            }\n        }\n\n        $pdo->commit();\n        echo \"<div class=\"alert alert-success\">Invoice created successfully! Invoice ID: $invoiceId</div>\";\n\n    } catch (Exception $e) {\n        $pdo->rollback();\n        echo \"<div class=\"alert alert-error\" style=\"color: red;\">Error: \" . htmlspecialchars($e->getMessage()) . \"</div>\";\n    }\n}\n\n// Fetch parties for dropdown\n$partiesStmt = $pdo->query(\"SELECT id, name, gstin FROM parties WHERE is_active = 1 ORDER BY name\");\n$parties = $partiesStmt->fetchAll();\n\n// Fetch items for dropdown  \n$itemsStmt = $pdo->query(\"SELECT id, code, name, hsn_code, rate, gst_rate FROM items WHERE is_active = 1 ORDER BY name\");\n$items = $itemsStmt->fetchAll();\n?>\n\n<div class=\"card\">\n    <div class=\"card-header\">\n        <h2>📄 Create New Invoice</h2>\n    </div>\n    \n    <form method=\"POST\" id=\"invoiceForm\">\n        <input type=\"hidden\" name=\"csrf_token\" value=\"<?php echo $_SESSION[\"csrf_token\"] ?? \"\"; ?>\">\n        \n        <div class=\"row\">\n            <div class=\"col-2\">\n                <div class=\"form-group\">\n                    <label for=\"invoice_no\">Invoice Number *</label>\n                    <input type=\"text\" id=\"invoice_no\" name=\"invoice_no\" class=\"form-control\" required \n                           value=\"INV-<?php echo date(\"Ymd\") . \"-\" . str_pad(rand(1,999), 3, \"0\", STR_PAD_LEFT); ?>\">\n                </div>\n            </div>\n            \n            <div class=\"col-2\">\n                <div class=\"form-group\">\n                    <label for=\"invoice_date\">Invoice Date *</label>\n                    <input type=\"date\" id=\"invoice_date\" name=\"invoice_date\" class=\"form-control\" \n                           value=\"<?php echo date(\"Y-m-d\"); ?>\" required>\n                </div>\n            </div>\n        </div>\n        \n        <div class=\"form-group\">\n            <label for=\"party_id\">Select Party *</label>\n            <select id=\"party_id\" name=\"party_id\" class=\"form-control\" required>\n                <option value=\"\">-- Select Party --</option>\n                <?php foreach ($parties as $party): ?>\n                    <option value=\"<?php echo $party[\"id\"]; ?>\" data-gstin=\"<?php echo $party[\"gstin\"]; ?>\">\n                        <?php echo htmlspecialchars($party[\"name\"]); ?> \n                        <?php if ($party[\"gstin\"]): ?>\n                            (<?php echo $party[\"gstin\"]; ?>)\n                        <?php endif; ?>\n                    </option>\n                <?php endforeach; ?>\n            </select>\n        </div>\n        \n        <div class=\"form-group\">\n            <label>Invoice Items</label>\n            <div id=\"items-container\">\n                <div class=\"item-row\" data-row=\"0\">\n                    <div class=\"row\">\n                        <div class=\"col-4\">\n                            <select name=\"items[0][item_id]\" class=\"form-control item-select\" required>\n                                <option value=\"\">-- Select Item --</option>\n                                <?php foreach ($items as $item): ?>\n                                    <option value=\"<?php echo $item[\"id\"]; ?>\" \n                                            data-hsn=\"<?php echo $item[\"hsn_code\"]; ?>\"\n                                            data-rate=\"<?php echo $item[\"rate\"]; ?>\"\n                                            data-gst=\"<?php echo $item[\"gst_rate\"]; ?>\">\n                                        <?php echo htmlspecialchars($item[\"name\"]); ?> (<?php echo $item[\"code\"]; ?>)\n                                    </option>\n                                <?php endforeach; ?>\n                            </select>\n                        </div>\n                        <div class=\"col\">\n                            <input type=\"number\" name=\"items[0][quantity]\" placeholder=\"Qty\" class=\"form-control\" value=\"1\" required>\n                        </div>\n                        <div class=\"col\">\n                            <input type=\"number\" name=\"items[0][rate]\" placeholder=\"Rate\" class=\"form-control\" step=\"0.01\" required>\n                        </div>\n                        <div class=\"col\">\n                            <input type=\"text\" name=\"items[0][hsn]\" placeholder=\"HSN\" class=\"form-control\">\n                        </div>\n                        <div class=\"col\">\n                            <button type=\"button\" class=\"btn btn-danger\" onclick=\"removeItem(0)\">Remove</button>\n                        </div>\n                    </div>\n                </div>\n            </div>\n            <button type=\"button\" id=\"add-item\" class=\"btn btn-secondary\">+ Add Item</button>\n        </div>\n        \n        <div class=\"row\">\n            <div class=\"col-2\">\n                <div class=\"form-group\">\n                    <label for=\"taxable_amount\">Taxable Amount</label>\n                    <input type=\"number\" id=\"taxable_amount\" name=\"taxable_amount\" class=\"form-control\" step=\"0.01\" readonly>\n                </div>\n            </div>\n            \n            <div class=\"col-2\">\n                <div class=\"form-group\">\n                    <label for=\"total_amount\">Total Amount</label>\n                    <input type=\"number\" id=\"total_amount\" name=\"total_amount\" class=\"form-control\" step=\"0.01\" readonly>\n                </div>\n            </div>\n        </div>\n        \n        <div class=\"form-group\">\n            <button type=\"submit\" class=\"btn btn-success\">💾 Create Invoice</button>\n            <a href=\"?page=invoices/list\" class=\"btn btn-secondary\">📋 View All Invoices</a>\n        </div>\n    </form>\n</div>\n\n<script>\nlet itemRowCount = 1;\n\ndocument.getElementById(\"add-item\").addEventListener(\"click\", function() {\n    const container = document.getElementById(\"items-container\");\n    const newRow = document.querySelector(\".item-row\").cloneNode(true);\n    \n    newRow.setAttribute(\"data-row\", itemRowCount);\n    newRow.querySelectorAll(\"select, input\").forEach(function(field) {\n        const name = field.getAttribute(\"name\");\n        if (name) {\n            field.setAttribute(\"name\", name.replace(\"[0]\", \"[\" + itemRowCount + \"]\"));\n        }\n        field.value = \"\";\n    });\n    \n    container.appendChild(newRow);\n    itemRowCount++;\n});\n\nfunction removeItem(rowIndex) {\n    const row = document.querySelector(\"[data-row=\"\" + rowIndex + \"\"]\");\n    if (document.querySelectorAll(\".item-row\").length > 1) {\n        row.remove();\n    }\n}\n\n// Auto-calculate totals\ndocument.addEventListener(\"change\", function(e) {\n    if (e.target.matches(\"input[name*=\"[quantity]\"], input[name*=\"[rate]\"]\")) {\n        calculateTotals();\n    }\n});\n\nfunction calculateTotals() {\n    let taxableAmount = 0;\n    \n    document.querySelectorAll(\".item-row\").forEach(function(row) {\n        const qty = parseFloat(row.querySelector(\"input[name*=\"[quantity]\"]\").value) || 0;\n        const rate = parseFloat(row.querySelector(\"input[name*=\"[rate]\"]\").value) || 0;\n        taxableAmount += qty * rate;\n    });\n    \n    document.getElementById(\"taxable_amount\").value = taxableAmount.toFixed(2);\n    document.getElementById(\"total_amount\").value = taxableAmount.toFixed(2);\n}\n</script>','invoices,invoice_items,parties'),
(4,'invoices/list','List Invoices','Invoices',2,'<?php\n$pdo = DB::conn();\necho \"<h1>Invoices</h1>\";\n\n$sql = \"SELECT i.id, i.invoice_no, i.invoice_date, i.party_name, i.inv_type, i.status,\n               COALESCE(SUM(it.line_total),0) AS total\n        FROM invoices i\n        LEFT JOIN invoice_items it ON i.id = it.invoice_id\n        GROUP BY i.id, i.invoice_no, i.invoice_date, i.party_name, i.inv_type, i.status\n        ORDER BY i.invoice_date DESC, i.id DESC\n        LIMIT 50\";\n\n$stmt = $pdo->query($sql);\n\necho \"<table border=1 cellpadding=6>\n<tr>\n  <th>ID</th>\n  <th>No</th>\n  <th>Date</th>\n  <th>Party</th>\n  <th>Type</th>\n  <th>Status</th>\n  <th>Total</th>\n</tr>\";\n\nforeach ($stmt as $row) {\n    echo \"<tr>\n        <td>{$row[\"id\"]}</td>\n        <td>\".htmlspecialchars($row[\"invoice_no\"]).\"</td>\n        <td>{$row[\"invoice_date\"]}</td>\n        <td>\".htmlspecialchars($row[\"party_name\"]).\"</td>\n        <td>{$row[\"inv_type\"]}</td>\n        <td>{$row[\"status\"]}</td>\n        <td style=\"text-align:right;\">\".number_format($row[\"total\"],2).\"</td>\n    </tr>\";\n}\necho \"</table>\";\n;?>','invoices,invoice_items'),
(5,'dashboard','Dashboard','Main',1,'<?php\n$pdo = DB::conn();\necho \"<h1>Dashboard</h1>\";\n$stmt = $pdo->query(\"SELECT COUNT(*) FROM invoices\");\necho \"<p>Total invoices: \".$stmt->fetchColumn().\"</p>\";\n;?>','invoices,invoice_items,parties'),
(19,'tools/manual-refresh-reminder','Manual Refresh Reminder','Tools',2,'<?php\n$pdo = DB::conn();\n$stmt = $pdo->prepare(\"SELECT setting_value FROM app_settings WHERE setting_key = ?\");\n$stmt->execute([\"dependency_refresh_command\"]);\n$cmd = $stmt->fetchColumn() ?: \"Command not configured.\";\n;?>\n<!DOCTYPE html>\n<html>\n<head>\n  <meta charset=\"UTF-8\">\n  <title>Manual Refresh Reminder</title>\n  <style>\n    body { font-family: Arial, sans-serif; background: #fff8dc; color: #333; padding: 20px; }\n    pre { background: #eee; padding: 12px; border-radius: 6px; }\n  </style>\n</head>\n<body>\n  <h1>🚨 Manual Dependency Refresh 🚨</h1>\n  <p>Run this command manually to refresh <b>tables_used</b> and rebuild dependency views:</p>\n  <pre><?php echo htmlspecialchars($cmd); ;?></pre>\n  <p>Copy and paste into your terminal whenever you need to refresh.</p>\n</body>\n</html>','app_settings'),
(30,'tools/diagnostics','Diagnostics','Tools',10,'<?php\n$pdo = DB::conn();\n\necho \"<h1>Diagnostics</h1>\";\n\n// Filters\n$level = $_GET[\"level\"] ?? \"\";\n$limit = (int)($_GET[\"limit\"] ?? 100);\nif ($limit <= 0 || $limit > 1000) $limit = 100;\n\n$where = \"\";\n$params = [];\nif (in_array($level, [\"INFO\",\"WARN\",\"ERROR\"])) {\n    $where = \"WHERE level = ?\";\n    $params[] = $level;\n}\n\n// Fetch logs\n$sql = \"SELECT id, created_at, level, message FROM diagnostics \" . $where . \" ORDER BY id DESC LIMIT ?\";\n$stmt = $pdo->prepare($sql);\nforeach ($params as $idx => $val) {\n    $stmt->bindValue($idx+1, $val);\n}\n$stmt->bindValue(count($params)+1, $limit, PDO::PARAM_INT);\n$stmt->execute();\n\necho \"<form method=\\\"get\\\">\n  <input type=\\\"hidden\\\" name=\\\"page\\\" value=\\\"tools/diagnostics\\\">\n  Level: \n  <select name=\\\"level\\\">\n    <option value=\\\"\\\">(All)</option>\n    <option value=\\\"INFO\\\" \".($level===\"INFO\"?\"selected\":\"\").\">INFO</option>\n    <option value=\\\"WARN\\\" \".($level===\"WARN\"?\"selected\":\"\").\">WARN</option>\n    <option value=\\\"ERROR\\\" \".($level===\"ERROR\"?\"selected\":\"\").\">ERROR</option>\n  </select>\n  Limit: <input name=\\\"limit\\\" value=\\\"\".$limit.\"\\\" size=\\\"4\\\">\n  <button type=\\\"submit\\\">Apply</button>\n</form>\";\n\necho \"<table border=1 cellpadding=6>\n<tr>\n  <th>ID</th>\n  <th>Time</th>\n  <th>Level</th>\n  <th>Message</th>\n</tr>\";\n\nforeach ($stmt as $row) {\n    echo \"<tr>\n      <td>\".$row[\"id\"].\"</td>\n      <td>\".$row[\"created_at\"].\"</td>\n      <td>\".$row[\"level\"].\"</td>\n      <td><pre style=\\\"margin:0;white-space:pre-wrap;\\\">\".htmlspecialchars($row[\"message\"]).\"</pre></td>\n    </tr>\";\n}\necho \"</table>\";\n\n// Quick self-test: log an INFO message (optional button)\nif ($_SERVER[\"REQUEST_METHOD\"] === \"POST\" && isset($_POST[\"self_test\"])) {\n    try {\n        $log = $pdo->prepare(\"INSERT INTO diagnostics (level, message) VALUES (?, ?)\");\n        $log->execute([\"INFO\", \"Self-test: diagnostics page is working\"]);\n        echo \"<p style=\\\"color:green;\\\">Self-test log inserted.</p>\";\n    } catch (Exception $e) {\n        echo \"<p style=\\\"color:red;\\\">Self-test failed: \".htmlspecialchars($e->getMessage()).\"</p>\";\n    }\n}\necho \"<form method=\\\"post\\\"><button name=\\\"self_test\\\" value=\\\"1\\\">Insert self-test log</button></form>\";\n;?>','diagnostics'),
(31,'parties/master','Party Master','Parties',1,'<?php\n$pdo = DB::conn();\n\nif ($_SERVER[\"REQUEST_METHOD\"] === \"POST\") {\n    try {\n        $stmt = $pdo->prepare(\"INSERT INTO parties (name, gstin, party_type, city, state, state_code) VALUES (?,?,?,?,?,?)\");\n        $stmt->execute([\n            $_POST[\"name\"],\n            $_POST[\"gstin\"] ?: null,\n            $_POST[\"party_type\"],\n            $_POST[\"city\"] ?: null,\n            $_POST[\"state\"] ?: null,\n            $_POST[\"state_code\"] ?: null\n        ]);\n        echo \"<p style=\"color:green;\">Party saved successfully.</p>\";\n    } catch (Exception $e) {\n        echo \"<p style=\"color:red;\">Error: \".htmlspecialchars($e->getMessage()).\"</p>\";\n    }\n}\n\necho \"<h1>Party Master</h1>\";\necho \"<form method=post>\n  <label>Name: <input name=name required></label><br>\n  <label>GSTIN: <input name=gstin maxlength=15></label><br>\n  <label>Type: \n    <select name=party_type>\n      <option value=\"customer\">Customer</option>\n      <option value=\"supplier\">Supplier</option>\n      <option value=\"both\">Both</option>\n    </select>\n  </label><br>\n  <label>City: <input name=city></label><br>\n  <label>State: <input name=state></label><br>\n  <label>State Code: <input name=state_code maxlength=2></label><br>\n  <button type=submit>Save</button>\n</form>\";\n\necho \"<h2>Existing Parties</h2>\";\n$stmt = $pdo->query(\"SELECT id, name, gstin, party_type, city, state, state_code FROM parties ORDER BY id DESC LIMIT 20\");\necho \"<table border=1 cellpadding=6><tr><th>ID</th><th>Name</th><th>GSTIN</th><th>Type</th><th>City</th><th>State</th><th>Code</th></tr>\";\nforeach ($stmt as $row) {\n    echo \"<tr>\n        <td>{$row[\"id\"]}</td>\n        <td>\".htmlspecialchars($row[\"name\"]).\"</td>\n        <td>\".htmlspecialchars($row[\"gstin\"]).\"</td>\n        <td>{$row[\"party_type\"]}</td>\n        <td>\".htmlspecialchars($row[\"city\"]).\"</td>\n        <td>\".htmlspecialchars($row[\"state\"]).\"</td>\n        <td>\".htmlspecialchars($row[\"state_code\"]).\"</td>\n    </tr>\";\n}\necho \"</table>\";\n;?>','parties'),
(36,'invoices/view','View Invoice','Invoices',3,'<?php\n$pdo = DB::conn();\n\n$invoiceId = $_GET[\"id\"] ?? null;\nif (!$invoiceId) {\n    echo \"<p style=\"color:red;\">No invoice ID provided.</p>\";\n    return;\n}\n\n// Fetch invoice header\n$stmt = $pdo->prepare(\"SELECT * FROM invoices WHERE id=?\");\n$stmt->execute([$invoiceId]);\n$inv = $stmt->fetch(PDO::FETCH_ASSOC);\n\nif (!$inv) {\n    echo \"<p style=\"color:red;\">Invoice not found.</p>\";\n    return;\n}\n\necho \"<h1>Invoice #\".htmlspecialchars($inv[\"invoice_no\"]).\"</h1>\";\necho \"<p>Date: \".$inv[\"invoice_date\"].\"</p>\";\necho \"<p>Party: \".htmlspecialchars($inv[\"party_name\"]).\" (GSTIN: \".htmlspecialchars($inv[\"party_gstin\"]).\")</p>\";\necho \"<p>Type: \".$inv[\"inv_type\"].\" | Status: \".$inv[\"status\"].\"</p>\";\n\n// Fetch items\n$stmt = $pdo->prepare(\"SELECT description, hsn, quantity, rate, cgst_rate, sgst_rate, igst_rate, line_total \n                       FROM invoice_items WHERE invoice_id=?\");\n$stmt->execute([$invoiceId]);\n\necho \"<h2>Items</h2>\";\necho \"<table border=1 cellpadding=6>\n<tr>\n  <th>Description</th>\n  <th>HSN</th>\n  <th>Qty</th>\n  <th>Rate</th>\n  <th>CGST%</th>\n  <th>SGST%</th>\n  <th>IGST%</th>\n  <th>Line Total</th>\n</tr>\";\n\n$total = 0;\nforeach ($stmt as $row) {\n    $total += $row[\"line_total\"];\n    echo \"<tr>\n        <td>\".htmlspecialchars($row[\"description\"]).\"</td>\n        <td>\".htmlspecialchars($row[\"hsn\"]).\"</td>\n        <td>\".$row[\"quantity\"].\"</td>\n        <td>\".$row[\"rate\"].\"</td>\n        <td>\".$row[\"cgst_rate\"].\"</td>\n        <td>\".$row[\"sgst_rate\"].\"</td>\n        <td>\".$row[\"igst_rate\"].\"</td>\n        <td style=\"text-align:right;\">\".number_format($row[\"line_total\"],2).\"</td>\n    </tr>\";\n}\necho \"<tr><td colspan=7 style=\"text-align:right;\"><strong>Total</strong></td>\n      <td style=\"text-align:right;\"><strong>\".number_format($total,2).\"</strong></td></tr>\";\necho \"</table>\";\n\necho \"<p><a href=\"new_index.php?page=invoices/list\">Back to list</a></p>\";\n;?>','invoices,invoice_items'),
(37,'invoices/print','Print Invoice','Invoices',4,'<?php\n$pdo = DB::conn();\n\n$invoiceId = $_GET[\"id\"] ?? null;\nif (!$invoiceId) {\n    echo \"<p style=\"color:red;\">No invoice ID provided.</p>\";\n    return;\n}\n\n// Fetch invoice header\n$stmt = $pdo->prepare(\"SELECT * FROM invoices WHERE id=?\");\n$stmt->execute([$invoiceId]);\n$inv = $stmt->fetch(PDO::FETCH_ASSOC);\n\nif (!$inv) {\n    echo \"<p style=\"color:red;\">Invoice not found.</p>\";\n    return;\n}\n\n// Fetch items\n$stmt = $pdo->prepare(\"SELECT description, hsn, quantity, rate, cgst_rate, sgst_rate, igst_rate, line_total \n                       FROM invoice_items WHERE invoice_id=?\");\n$stmt->execute([$invoiceId]);\n$items = $stmt->fetchAll(PDO::FETCH_ASSOC);\n\n// Print‑friendly HTML;?>\n<!DOCTYPE html>\n<html>\n<head>\n  <meta charset=\"UTF-8\">\n  <title>Invoice #<?php echo htmlspecialchars($inv[\"invoice_no\"]); ;?></title>\n  <style>\n    body { font-family: Arial, sans-serif; margin: 40px; color: #000; }\n    h1, h2 { margin: 0; }\n    .header { display: flex; justify-content: space-between; margin-bottom: 20px; }\n    .party { margin-top: 10px; }\n    table { border-collapse: collapse; width: 100%; margin-top: 20px; }\n    th, td { border: 1px solid #000; padding: 6px; text-align: left; }\n    th { background: #f0f0f0; }\n    .total-row td { font-weight: bold; }\n    @media print {\n      button { display: none; }\n    }\n  </style>\n</head>\n<body>\n  <div class=\"header\">\n    <div>\n      <h1>Invoice</h1>\n      <p>No: <?php echo htmlspecialchars($inv[\"invoice_no\"]); ;?><br>\n         Date: <?php echo $inv[\"invoice_date\"]; ;?><br>\n         Type: <?php echo $inv[\"inv_type\"]; ;?></p>\n    </div>\n    <div>\n      <h2><?php echo htmlspecialchars($inv[\"party_name\"]); ;?></h2>\n      <p class=\"party\">\n        GSTIN: <?php echo htmlspecialchars($inv[\"party_gstin\"]); ;?><br>\n        City: <?php echo htmlspecialchars($inv[\"city\"]); ;?><br>\n        State: <?php echo htmlspecialchars($inv[\"state\"]); ;?>\n      </p>\n    </div>\n  </div>\n\n  <table>\n    <tr>\n      <th>Description</th>\n      <th>HSN</th>\n      <th>Qty</th>\n      <th>Rate</th>\n      <th>CGST%</th>\n      <th>SGST%</th>\n      <th>IGST%</th>\n      <th>Line Total</th>\n    </tr>\n    <?php $grand=0; foreach ($items as $row): $grand += $row[\"line_total\"]; ;?>\n    <tr>\n      <td><?php echo htmlspecialchars($row[\"description\"]); ;?></td>\n      <td><?php echo htmlspecialchars($row[\"hsn\"]); ;?></td>\n      <td><?php echo $row[\"quantity\"]; ;?></td>\n      <td><?php echo number_format($row[\"rate\"],2); ;?></td>\n      <td><?php echo $row[\"cgst_rate\"]; ;?></td>\n      <td><?php echo $row[\"sgst_rate\"]; ;?></td>\n      <td><?php echo $row[\"igst_rate\"]; ;?></td>\n      <td style=\"text-align:right;\"><?php echo number_format($row[\"line_total\"],2); ;?></td>\n    </tr>\n    <?php endforeach; ;?>\n    <tr class=\"total-row\">\n      <td colspan=\"7\" style=\"text-align:right;\">Grand Total</td>\n      <td style=\"text-align:right;\"><?php echo number_format($grand,2); ;?></td>\n    </tr>\n  </table>\n\n  <button onclick=\"window.print()\">🖨 Print</button>\n</body>\n</html>\n<?php;?>','invoices,invoice_items,parties'),
(38,'tools/gst-summary','GST Summary','Tools',5,'<?php\n$pdo = DB::conn();\n\necho \"<h1>GST Summary</h1>\";\n\n$sql = \"SELECT \n            DATE_FORMAT(i.invoice_date, \'%Y-%m\') AS period,\n            SUM(it.taxable_amount) AS taxable_value,\n            SUM(it.cgst_amount) AS cgst_total,\n            SUM(it.sgst_amount) AS sgst_total,\n            SUM(it.igst_amount) AS igst_total,\n            SUM(it.line_total) AS grand_total\n        FROM invoices i\n        JOIN invoice_items it ON i.id = it.invoice_id\n        WHERE i.status <> \'cancelled\'\n        GROUP BY DATE_FORMAT(i.invoice_date, \'%Y-%m\')\n        ORDER BY period DESC\";\n\n$stmt = $pdo->query($sql);\n\necho \"<table border=1 cellpadding=6>\n<tr>\n  <th>Period (YYYY-MM)</th>\n  <th>Taxable Value</th>\n  <th>CGST</th>\n  <th>SGST</th>\n  <th>IGST</th>\n  <th>Grand Total</th>\n</tr>\";\n\nforeach ($stmt as $row) {\n    echo \"<tr>\n        <td>{$row[\"period\"]}</td>\n        <td style=\"text-align:right;\">\".number_format($row[\"taxable_value\"],2).\"</td>\n        <td style=\"text-align:right;\">\".number_format($row[\"cgst_total\"],2).\"</td>\n        <td style=\"text-align:right;\">\".number_format($row[\"sgst_total\"],2).\"</td>\n        <td style=\"text-align:right;\">\".number_format($row[\"igst_total\"],2).\"</td>\n        <td style=\"text-align:right;\">\".number_format($row[\"grand_total\"],2).\"</td>\n    </tr>\";\n}\necho \"</table>\";\n;?>','invoices,invoice_items');
